const tourDayNames={17:'Sábado',18:'Domingo',19:'Lunes'};
const tourMap=q=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
function tourCard(t){return `<article class="tour-card" id="tour-${t.id}">${t.image?`<img src="assets/${t.image}" alt="Recreación familiar con IA; no es una fotografía del operador" loading="lazy" width="1672" height="941">`:'<div class="tour-coffee" aria-hidden="true">Café, del origen a la taza.</div>'}<div class="tour-body"><p class="eyebrow">${t.tag}</p><div class="tour-score"><strong>★ ${t.rating.toFixed(1)} / 5</strong><span>${t.reviews} opiniones</span></div><h3>${t.title}</h3><p class="fine">${t.duration} · Código ${t.id}</p><p>${t.description}</p><details open><summary>Cómo encaja en nuestro día</summary><p>${t.fit}</p></details><details><summary>Dónde nos encontramos y qué confirmar</summary><p>${t.logistics}</p><p>${t.extra}</p>${ext(tourMap(t.map),'Ver ubicación propuesta')}</details><div class="tour-actions">${ext(t.url,'Consultar en Viator','button')}${t.ratingSource?ext(t.ratingSource,'Fuente de valoración'):''}</div><p class="fine">Buscar ${t.original}. Seleccionar ${t.day}/10/2026, 4 adultos y español. Horario, precio y cupos pendientes de confirmar.</p></div></article>`;}
document.querySelector('#tours').innerHTML=`<div class="section-heading"><p class="eyebrow">CON GUÍA, EN BUENA COMPAÑÍA</p><h2>Tours para compartir los cuatro.</h2><p>Selección de Viator para el 17, 18 y 19 de octubre de 2026. Todas las experiencias incluidas alcanzan 4.7/5 o más en las fuentes consultadas el 20 de septiembre de 2026.</p></div><div class="tour-notice"><b>Opciones para elegir · todavía sin reservar</b><p>Las valoraciones pueden cambiar y reúnen opiniones de Viator y Tripadvisor. No se han confirmado cupos para estas fechas. Abrir cada ficha, elegir fecha, 4 adultos e idioma, y comprobar el precio total, las inclusiones y la cancelación antes de pagar. Las fotos familiares son recreaciones con IA.</p><p>El itinerario y sus mapas mantienen el plan base hasta que elijan un tour. Abajo se indica cuándo cambia un encuentro. No sumar las alternativas al mismo día.</p></div>${[17,18,19].map(day=>`<div class="tour-day" id="tours-${day}"><h3>${tourDayNames[day]} ${day} de octubre</h3><div class="tour-grid">${viatorTours.filter(t=>t.day===day).map(tourCard).join('')}</div></div>`).join('')}<p class="fine">Sabaneta: el tour de tres municipios consultado muestra reseñas del operador, pero ninguna propia de la experiencia. Por eso no se incluye entre los tours con valoración mínima verificada. El paseo independiente de Sabaneta sigue disponible en el plan base del lunes.</p>`;
function renderTourDay(){document.querySelector('.daily-tour-link')?.remove();const id=Number(location.hash.match(/^#dia-(\d+)$/)?.[1]||13);if(![17,18,19].includes(id))return;const n=document.createElement('div');n.className='tour-notice daily-tour-link';n.innerHTML=`<b>Viator · opciones de 4.7/5 o más para este día</b><p>${id===17?'Grafiti de 3 horas o ciudad + Comuna 13 de jornada completa.':id===18?'Arví con guía: comprobar modalidad, inicio y billetes incluidos.':'Café con degustación: sustituye el encuentro y almuerzo de Sabaneta.'} Los encuentros del plan base cambian si la opción elegida lo requiere.</p><a class="button light" href="#tours-${id}">Ver tours del ${id} de octubre ↓</a>`;document.querySelector('#day-content .day-intro').after(n);}
window.addEventListener('hashchange',()=>{if(/^#dia-\d+$/.test(location.hash))renderTourDay();});renderTourDay();
